        onPreviousMonth = vm::onPreviousMonth,
        onNextMonth = vm::onNextMonth,
        modifier = modifier
    )
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun StreakContent(
    state: StreakUiState,
    onBackClick: () -> Unit,
    onDaySelected: (LocalDate) -> Unit,
    onDayDismissed: () -> Unit,
    onPreviousMonth: () -> Unit,
    onNextMonth: () -> Unit,
    modifier: Modifier = Modifier
) {
    Scaffold(
        modifier = modifier,
        containerColor = MaterialTheme.colorScheme.background,
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        "Chuỗi ngày",
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                },
                navigationIcon = {
                    IconButton(onClick = onBackClick) {
                    Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Quay lại")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.surface
                )
            )
        }
    ) { innerPadding ->
        if (state.isLoading) {
            Box(
                Modifier
                    .fillMaxSize()
                    .padding(innerPadding),
                contentAlignment = Alignment.Center
            ) { CircularProgressIndicator(color = StreakOrange) }
        } else {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(innerPadding)
                    .padding(horizontal = 16.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                Spacer(Modifier.height(4.dp))

                // ─── Stats row ───────────────────────────────────────────────
                StreakStatsRow(
                    currentStreak = state.currentStreak,
                    longestStreak = state.longestStreak,
                    todayCount    = state.todayTransactionCount
                )

                // ─── Calendar ────────────────────────────────────────────────
                StreakCalendar(
                    displayMonth  = state.displayMonth,
                    daySummaryMap = state.daySummaryMap,
                    selectedDate  = state.selectedDate,
                    onPrevious    = onPreviousMonth,
                    onNext        = onNextMonth,
                    onDayClick    = onDaySelected
                )
            }
        }

        // ─── Bottom sheet chi tiết ngày ─────────────────────────────────────
        if (state.selectedDate != null) {
            val sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)
            ModalBottomSheet(
                onDismissRequest = onDayDismissed,
                sheetState = sheetState,
                containerColor = MaterialTheme.colorScheme.surface
            ) {
                DayDetailSheet(
                    date    = state.selectedDate,
                    summary = state.selectedDaySummary
                )
            }
        }
    }
}

// ─── Stats cards ──────────────────────────────────────────────────────────────

@Composable
private fun StreakStatsRow(
    currentStreak: Int,
    longestStreak: Int,
