        )
        StatCard(
            modifier = Modifier.weight(1f),
            icon = {
                Text("", fontSize = 22.sp)
            },
            value = "$todayCount GD",
            label = "Hôm nay"
        )
    }
}

@Composable
private fun StatCard(
    icon: @Composable () -> Unit,
    value: String,
    label: String,
    modifier: Modifier = Modifier
) {
    Card(
        modifier = modifier,
        shape = RoundedCornerShape(16.dp),
