/**
 * Service gọi Groq API (MIỄN PHÍ) - model llama3-8b-8192
 * Lấy key tại: https://console.groq.com/keys
 * Free tier: 30 req/phút, 14,400 req/ngày — thoải mái hơn Gemini nhiều
 */
object GroqService {
    private const val TAG = "GroqService"
    private const val GROQ_URL = "https://api.groq.com/openai/v1/chat/completions"
    private const val MODEL = "llama-3.3-70b-versatile"

    private val SYSTEM_PROMPT = """
        Bạn là trợ lý tài chính AI trong ứng dụng MyMoney.
        Khi người dùng nhắn một giao dịch (ví dụ: "bữa tối 20k", "lương 10tr"), bạn phải:
        1. Phản hồi ngắn gọn, vui vẻ bằng tiếng Việt (1-2 câu, có thể dùng emoji)
        2. Trả về JSON ở cuối trong block ```json ... ```

        Format JSON bắt buộc:
        ```json
        {
          "transactions": [
            {
              "note": "Tên giao dịch",
              "amount": 20000,
              "type": "expense",
              "category": "Ăn uống"
            }
          ]
        }
        ```

        Quy tắc chuyển đổi số tiền:
        - "k" hoặc "K" = × 1,000  (20k → 20000)
        - "tr" hoặc "triệu" = × 1,000,000  (10tr → 10000000)
        - Số thuần túy = nguyên xi (500000 → 500000)

        Quy tắc xác định type:
        - Mặc định: "expense" (chi tiêu)
        - "income" khi rõ ràng là thu nhập: lương, thưởng, nhận tiền, bán hàng...

        Danh mục (category) gợi ý:
        - Chi tiêu: Ăn uống, Di chuyển, Mua sắm, Giải trí, Sức khỏe, Giáo dục, Hóa đơn, Khác
        - Thu nhập: Thu nhập, Thưởng, Đầu tư, Khác

        Nếu tin nhắn không liên quan đến giao dịch tài chính,
        hãy trả lời thân thiện và KHÔNG trả về JSON.
    """.trimIndent()

    private val json = Json { ignoreUnknownKeys = true }

    private val client = HttpClient(Android) {
        install(ContentNegotiation) {
            json(json)
        }
    }

    // ── Request ──
    @Serializable
    private data class ChatRequest(
        val model: String,
        val messages: List<Message>,
        @SerialName("max_tokens") val maxTokens: Int = 1024,
        val temperature: Double = 0.7
    )

    @Serializable
    private data class Message(val role: String, val content: String)

    // ── Response (success) ──
    @Serializable
    private data class ChatResponse(val choices: List<Choice>)

    @Serializable
    private data class Choice(val message: Message)

    // ── Response (error) ──
    @Serializable
    private data class ErrorWrapper(val error: ErrorDetail? = null)

    @Serializable
    private data class ErrorDetail(
        val message: String = "Unknown error",
        val type: String = "",
        val code: String = ""
    )

    /**
     * Gửi tin nhắn tới Groq (llama3-8b) và nhận phản hồi.
     * Giao diện giữ nguyên tên "GroqService.chat()" để không cần sửa ViewModel.
     */
    suspend fun chat(userMessage: String): String {
        return chatWithParsing(userMessage).displayText
    }

    /**
     * Kết quả parse từ Groq: text hiển thị + danh sách giao dịch đã parse.
     */
    data class ChatResult(
        val displayText: String,
        val transactions: List<ParsedTransaction> = emptyList()
    )

    /**
     * Giao dịch đã được AI parse ra từ tin nhắn.
     */
    data class ParsedTransaction(
        val note: String,
        val amount: Double,
        val type: String,       // "income" | "expense"
        val category: String
    )

    /**
     * Gửi tin nhắn, parse JSON giao dịch từ response nếu có.
     * Trả về [ChatResult] gồm text hiển thị + list giao dịch đã parse.
     */
    suspend fun chatWithParsing(userMessage: String): ChatResult {
        val apiKey = BuildConfig.GROQ_API_KEY
        if (apiKey.isBlank()) {
            Log.e(TAG, "⚠️ GROQ_API_KEY trống!")
            throw IllegalStateException("GROQ_API_KEY chưa cấu hình. Thêm vào local.properties")
        }

        val httpResponse = try {
            client.post(GROQ_URL) {
                header("Authorization", "Bearer $apiKey")
                contentType(ContentType.Application.Json)
                setBody(
                    ChatRequest(
                        model = MODEL,
                        messages = listOf(
                            Message(role = "system", content = SYSTEM_PROMPT),
                            Message(role = "user", content = userMessage)
                        )
                    )
                )
            }
        } catch (e: Exception) {
            Log.e(TAG, "Network error: ${e.message}", e)
            throw e
        }

        val rawBody = httpResponse.bodyAsText()
        Log.d(TAG, "HTTP ${httpResponse.status.value}: $rawBody")

        if (!httpResponse.status.isSuccess()) {
            val errorWrapper = runCatching { json.decodeFromString<ErrorWrapper>(rawBody) }.getOrNull()
            val errorMsg = errorWrapper?.error?.message ?: "HTTP ${httpResponse.status.value}"
            throw Exception(errorMsg)
        }

        val response = json.decodeFromString<ChatResponse>(rawBody)
        val fullText = response.choices.firstOrNull()?.message?.content
            ?: "Xin lỗi, mình chưa hiểu ý bạn. Thử lại nhé! "

        // Tách phần text hiển thị (bỏ JSON block)
        val displayText = fullText
            .replace(Regex("```json[\\s\\S]*?```"), "")
            .trim()
            .ifBlank { "✅ Đã ghi nhận giao dịch!" }

        // Tìm và parse JSON block nếu có
        val jsonMatch = Regex("```json([\\s\\S]*?)```").find(fullText)
        val transactions = if (jsonMatch != null) {
            try {
                val jsonBlock = jsonMatch.groupValues[1].trim()
                val parsed = json.decodeFromString<TransactionListWrapper>(jsonBlock)
                parsed.transactions.map { dto ->
                    ParsedTransaction(
                        note     = dto.note,
                        amount   = dto.amount,
                        type     = dto.type,
                        category = dto.category
                    )
                }
            } catch (e: Exception) {
                Log.w(TAG, "Failed to parse transaction JSON: ${e.message}")
                emptyList()
            }
        } else emptyList()

        Log.d(TAG, "Parsed ${transactions.size} transaction(s)")
        return ChatResult(displayText = displayText, transactions = transactions)
    }

    /**
     * Nhận dạng giọng nói từ file audio bằng Groq Whisper API.
     * @param audioFile File âm thanh (m4a/mp4) đã ghi từ VoiceRecorder
     * @return Văn bản đã nhận dạng
     */
    suspend fun transcribeAudio(audioFile: File): String {
        val apiKey = BuildConfig.GROQ_API_KEY
        if (apiKey.isBlank()) throw IllegalStateException("GROQ_API_KEY chưa cấu hình")

        val audioBytes = audioFile.readBytes()
        val response = client.post("https://api.groq.com/openai/v1/audio/transcriptions") {
            header("Authorization", "Bearer $apiKey")
            setBody(
                MultiPartFormDataContent(
                    formData {
                        append("model", "whisper-large-v3")
                        append("language", "vi")
                        append("response_format", "text")
                        append(
                            key = "file",
                            value = audioBytes,
                            headers = Headers.build {
                                append(HttpHeaders.ContentType, "audio/mp4")
                                append(
                                    HttpHeaders.ContentDisposition,
                                    "form-data; name=\"file\"; filename=\"audio.m4a\""
                                )
                            }
                        )
                    }
                )
            )
        }

        if (!response.status.isSuccess()) {
            val errorText = response.bodyAsText()
            Log.e(TAG, "Whisper error ${response.status.value}: $errorText")
            throw Exception("Lỗi nhận dạng giọng nói: ${response.status.value}")
        }
        val result = response.bodyAsText().trim()
        Log.d(TAG, "Whisper transcript: $result")
        return result
    }

    @Serializable
    private data class TransactionListWrapper(
        val transactions: List<ParsedTransactionDto> = emptyList()
    )

    @Serializable
    private data class ParsedTransactionDto(
        val note: String = "",
        val amount: Double = 0.0,
        val type: String = "expense",
        val category: String = "Khác"
    )
}

package com.example.mymoney.data.remote

import android.util.Log
import com.example.mymoney.BuildConfig
import io.ktor.client.HttpClient
import io.ktor.client.engine.android.Android
import io.ktor.client.plugins.contentnegotiation.ContentNegotiation
import io.ktor.client.request.header
import io.ktor.client.request.post
import io.ktor.client.request.setBody
import io.ktor.client.statement.bodyAsText
import io.ktor.http.ContentType
import io.ktor.http.contentType
import io.ktor.http.isSuccess
import io.ktor.serialization.kotlinx.json.json
import java.io.File
import java.util.UUID
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/**
 * Service gọi Groq API (MIỄN PHÍ) - model llama3-8b-8192
 * Lấy key tại: https://console.groq.com/keys
 * Free tier: 30 req/phút, 14,400 req/ngày — thoải mái hơn Gemini nhiều
 */
object GroqService {
    private const val TAG = "GroqService"
    private const val GROQ_URL = "https://api.groq.com/openai/v1/chat/completions"
    private const val MODEL = "llama-3.3-70b-versatile"

    private val SYSTEM_PROMPT = """
        Bạn là trợ lý tài chính AI trong ứng dụng MyMoney.
        Khi người dùng nhắn một giao dịch (ví dụ: "bữa tối 20k", "lương 10tr"), bạn phải:
        1. Phản hồi ngắn gọn, vui vẻ bằng tiếng Việt (1-2 câu, có thể dùng emoji)
        2. Trả về JSON ở cuối trong block ```json ... ```

        Format JSON bắt buộc:
        ```json
        {
          "transactions": [
            {
              "note": "Tên giao dịch",
              "amount": 20000,
              "type": "expense",
              "category": "Ăn uống"
            }
          ]
        }
        ```

        Quy tắc chuyển đổi số tiền:
        - "k" hoặc "K" = × 1,000  (20k → 20000)
        - "tr" hoặc "triệu" = × 1,000,000  (10tr → 10000000)
        - Số thuần túy = nguyên xi (500000 → 500000)

        Quy tắc xác định type:
        - Mặc định: "expense" (chi tiêu)
        - "income" khi rõ ràng là thu nhập: lương, thưởng, nhận tiền, bán hàng...

        Danh mục (category) gợi ý:
        - Chi tiêu: Ăn uống, Di chuyển, Mua sắm, Giải trí, Sức khỏe, Giáo dục, Hóa đơn, Khác
        - Thu nhập: Thu nhập, Thưởng, Đầu tư, Khác

        Nếu tin nhắn không liên quan đến giao dịch tài chính,
        hãy trả lời thân thiện và KHÔNG trả về JSON.
    """.trimIndent()

    private val json = Json { ignoreUnknownKeys = true }

    private val client = HttpClient(Android) {
        install(ContentNegotiation) {
            json(json)
        }
    }

    // ── Request ──
    @Serializable
    private data class ChatRequest(
        val model: String,
        val messages: List<Message>,
        @SerialName("max_tokens") val maxTokens: Int = 1024,
        val temperature: Double = 0.7
    )

    @Serializable
    private data class Message(val role: String, val content: String)

    // ── Response (success) ──
    @Serializable
    private data class ChatResponse(val choices: List<Choice>)

    @Serializable
    private data class Choice(val message: Message)

    // ── Response (error) ──
    @Serializable
    private data class ErrorWrapper(val error: ErrorDetail? = null)

    @Serializable
    private data class ErrorDetail(
        val message: String = "Unknown error",
        val type: String = "",
        val code: String = ""
    )

    /**
     * Gửi tin nhắn tới Groq (llama3-8b) và nhận phản hồi.
     * Giao diện giữ nguyên tên "GroqService.chat()" để không cần sửa ViewModel.
     */
    suspend fun chat(userMessage: String): String {
        return chatWithParsing(userMessage).displayText
    }

    /**
     * Kết quả parse từ Groq: text hiển thị + danh sách giao dịch đã parse.
     */
    data class ChatResult(
        val displayText: String,
        val transactions: List<ParsedTransaction> = emptyList()
    )

    /**
     * Giao dịch đã được AI parse ra từ tin nhắn.
     */
    data class ParsedTransaction(
        val note: String,
        val amount: Double,
        val type: String,       // "income" | "expense"
        val category: String
    )

    /**
     * Gửi tin nhắn, parse JSON giao dịch từ response nếu có.
     * Trả về [ChatResult] gồm text hiển thị + list giao dịch đã parse.
     */
    suspend fun chatWithParsing(userMessage: String): ChatResult {
        val apiKey = BuildConfig.GROQ_API_KEY
        if (apiKey.isBlank()) {
            Log.e(TAG, "⚠️ GROQ_API_KEY trống!")
            throw IllegalStateException("GROQ_API_KEY chưa cấu hình. Thêm vào local.properties")
        }

        val httpResponse = try {
            client.post(GROQ_URL) {
                header("Authorization", "Bearer $apiKey")
                contentType(ContentType.Application.Json)
                setBody(
                    ChatRequest(
                        model = MODEL,
                        messages = listOf(
                            Message(role = "system", content = SYSTEM_PROMPT),
                            Message(role = "user", content = userMessage)
                        )
                    )
                )
            }
        } catch (e: Exception) {
            Log.e(TAG, "Network error: ${e.message}", e)
            throw e
        }

        val rawBody = httpResponse.bodyAsText()
        Log.d(TAG, "HTTP ${httpResponse.status.value}: $rawBody")

        if (!httpResponse.status.isSuccess()) {
            val errorWrapper = runCatching { json.decodeFromString<ErrorWrapper>(rawBody) }.getOrNull()
            val errorMsg = errorWrapper?.error?.message ?: "HTTP ${httpResponse.status.value}"
            throw Exception(errorMsg)
        }

        val response = json.decodeFromString<ChatResponse>(rawBody)
        val fullText = response.choices.firstOrNull()?.message?.content
            ?: "Xin lỗi, mình chưa hiểu ý bạn. Thử lại nhé! "

        // Tách phần text hiển thị (bỏ JSON block)
        val displayText = fullText
            .replace(Regex("```json[\\s\\S]*?```"), "")
            .trim()
            .ifBlank { "✅ Đã ghi nhận giao dịch!" }

        // Tìm và parse JSON block nếu có
        val jsonMatch = Regex("```json([\\s\\S]*?)```").find(fullText)
        val transactions = if (jsonMatch != null) {
            try {
                val jsonBlock = jsonMatch.groupValues[1].trim()
                val parsed = json.decodeFromString<TransactionListWrapper>(jsonBlock)
                parsed.transactions.map { dto ->
                    ParsedTransaction(
                        note     = dto.note,
                        amount   = dto.amount,
                        type     = dto.type,
                        category = dto.category
                    )
                }
            } catch (e: Exception) {
                Log.w(TAG, "Failed to parse transaction JSON: ${e.message}")
                emptyList()
            }
        } else emptyList()

        Log.d(TAG, "Parsed ${transactions.size} transaction(s)")
        return ChatResult(displayText = displayText, transactions = transactions)
    }

    /**
     * Nhận dạng giọng nói từ file audio bằng Groq Whisper API.
     * @param audioFile File âm thanh (m4a/mp4) đã ghi từ VoiceRecorder
     * @return Văn bản đã nhận dạng
     */
    suspend fun transcribeAudio(audioFile: File): String {
        val apiKey = BuildConfig.GROQ_API_KEY
        if (apiKey.isBlank()) throw IllegalStateException("GROQ_API_KEY chưa cấu hình")

        Log.d(TAG, "Uploading audio file: ${audioFile.absolutePath} (${audioFile.length()} bytes)")

        // Manually create multipart payload
        val boundary = UUID.randomUUID().toString()
        val body = buildMultipartBody(boundary, audioFile)

        val response = client.post("https://api.groq.com/openai/v1/audio/transcriptions") {
            header("Authorization", "Bearer $apiKey")
            header("Content-Type", "multipart/form-data; boundary=$boundary")
            setBody(body)
        }

        if (!response.status.isSuccess()) {
            val errorText = response.bodyAsText()
            Log.e(TAG, "Whisper error ${response.status.value}: $errorText")
            throw Exception("Lỗi nhận dạng giọng nói: ${response.status.value}")
        }
        val result = response.bodyAsText().trim()
        Log.d(TAG, "Whisper transcript: $result")
        return result
    }

    private fun buildMultipartBody(boundary: String, audioFile: File): ByteArray {
        val sb = StringBuilder()
        val CRLF = "\r\n"

        // model field
        sb.append("--$boundary$CRLF")
        sb.append("Content-Disposition: form-data; name=\"model\"$CRLF")
        sb.append("$CRLF")
        sb.append("whisper-large-v3$CRLF")

        // language field
        sb.append("--$boundary$CRLF")
        sb.append("Content-Disposition: form-data; name=\"language\"$CRLF")
        sb.append("$CRLF")
        sb.append("vi$CRLF")

        // response_format field
        sb.append("--$boundary$CRLF")
        sb.append("Content-Disposition: form-data; name=\"response_format\"$CRLF")
        sb.append("$CRLF")
        sb.append("text$CRLF")

        // file field
        sb.append("--$boundary$CRLF")
        sb.append("Content-Disposition: form-data; name=\"file\"; filename=\"audio.m4a\"$CRLF")
        sb.append("Content-Type: audio/m4a$CRLF")
        sb.append("$CRLF")

        val headerBytes = sb.toString().toByteArray(Charsets.UTF_8)
        val fileBytes = audioFile.readBytes()
        val footerBytes = "$CRLF--$boundary--$CRLF".toByteArray(Charsets.UTF_8)

        val result = ByteArray(headerBytes.size + fileBytes.size + footerBytes.size)
        var pos = 0

        System.arraycopy(headerBytes, 0, result, pos, headerBytes.size)
        pos += headerBytes.size

        System.arraycopy(fileBytes, 0, result, pos, fileBytes.size)
        pos += fileBytes.size

        System.arraycopy(footerBytes, 0, result, pos, footerBytes.size)

        return result
    }

    @Serializable
    private data class TransactionListWrapper(
        val transactions: List<ParsedTransactionDto> = emptyList()
    )

    @Serializable
    private data class ParsedTransactionDto(
        val note: String = "",
        val amount: Double = 0.0,
        val type: String = "expense",
        val category: String = "Khác"
    )
}

package com.example.mymoney.presentation.viewmodel.addtransaction

import android.util.Log
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.mymoney.data.audio.VoiceRecorder
import com.example.mymoney.data.local.dao.CategoryDao
import com.example.mymoney.data.local.datastore.SettingPreferences
import com.example.mymoney.data.remote.GroqService
import com.example.mymoney.data.repository.SupabaseTransactionRepository
import com.example.mymoney.domain.model.ChatMessageModel
import com.example.mymoney.domain.model.TransactionModel
import com.example.mymoney.domain.repository.ChatRepository
import com.example.mymoney.domain.repository.WalletRepository
import com.example.mymoney.domain.usecase.AddTransactionUseCase
import com.example.mymoney.domain.usecase.EnsureDefaultWalletUseCase
import com.example.mymoney.domain.usecase.GetTransactionsUseCase
import com.example.mymoney.domain.usecase.MoneyFormatter
import com.example.mymoney.presentation.viewmodel.addtransaction.addtransaction.AddTransactionEvent
import com.example.mymoney.presentation.viewmodel.addtransaction.addtransaction.AddTransactionNavEvent
import com.example.mymoney.presentation.viewmodel.addtransaction.addtransaction.AddTransactionUiState
import com.example.mymoney.presentation.viewmodel.addtransaction.addtransaction.ChatMessage
import com.example.mymoney.presentation.viewmodel.addtransaction.addtransaction.ChatSender
import com.example.mymoney.presentation.viewmodel.addtransaction.addtransaction.VoiceRecordingState
import kotlinx.coroutines.Job
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.take
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

/**
 * ViewModel cho AIChatScreen.
 *
 * Luồng đầy đủ khi user nhắn "bữa tối 20k":
 *  1. Hiển thị bubble user + bubble "..." ngay lập tức
 *  2. Lưu tin nhắn user vào Room (chat_messages)
 *  3. Gọi Groq API → parse ra { note, amount, type, category }
 *  4. Thay "..." bằng phản hồi AI
 *  5. Lưu tin nhắn AI vào Room
 *  6. Với mỗi giao dịch parse được:
 *     a. Lấy/tạo ví mặc định của user
 *     b. Lưu TransactionModel vào Room (kèm walletId)
 *     c. Cập nhật balance ví trong Room (income → cộng, expense → trừ)
 *     d. Lưu lên Supabase song song (không block UI)
 */
class AddTransactionViewModel(
    @Suppress("unused")
    private val getTransactionsUseCase: GetTransactionsUseCase,
    private val addTransactionUseCase: AddTransactionUseCase,
    private val walletRepository: WalletRepository,
    private val ensureDefaultWallet: EnsureDefaultWalletUseCase,
    private val chatRepository: ChatRepository,
    private val supabaseTransactionRepo: SupabaseTransactionRepository,
    private val settingPreferences: SettingPreferences,
    private val categoryDao: CategoryDao,
    /** ID ví đang active trên HomeScreen. 0L = chưa chọn → fallback về ví mặc định. */
    private val selectedWalletId: Long = 0L,
    /** ApplicationContext để tạo VoiceRecorder */
    appContext: android.content.Context
) : ViewModel() {

    private val TAG = "AddTransactionVM"

    private val voiceRecorder = VoiceRecorder(appContext)

    private val _uiState = MutableStateFlow(AddTransactionUiState())
    val uiState: StateFlow<AddTransactionUiState> = _uiState.asStateFlow()

    private val _navEvent = MutableSharedFlow<AddTransactionNavEvent>()
    val navEvent: SharedFlow<AddTransactionNavEvent> = _navEvent.asSharedFlow()

    // sessionId là field của ViewModel — KHÔNG nằm trong UiState
    // → tạo 1 lần duy nhất, không mất khi recompose
    // → restore = dùng lại sessionId cũ nhất của user
    private var sessionId: String = java.util.UUID.randomUUID().toString()

    private var messageIdCounter = 0L
    private var isWaitingForAI = false
    private var submitDebounceJob: Job? = null

    init {
        viewModelScope.launch {
            // 1. Xóa tin nhắn cũ > 48h
            runCatching { chatRepository.deleteOldMessages() }

            val userId = settingPreferences.currentUserId.first() ?: return@launch

            // 2. Seed danh mục mặc định nếu chưa có (idempotent)
            runCatching {
                com.example.mymoney.data.repository.CategoryRepositoryImpl(categoryDao)
                    .seedDefaultCategories(userId)
            }

            // 2. Restore sessionId của phiên gần nhất (nếu có)
            val latestSession = runCatching {
                chatRepository.getLatestSessionId(userId)
            }.getOrNull()

            if (latestSession != null) {
                // Có lịch sử → dùng lại session cũ
                sessionId = latestSession
            }
            // Nếu null → giữ sessionId mới tạo (lần đầu dùng app)

            // 3. Load lịch sử tin nhắn từ Room một lần (take(1)) khi khởi động
            // Sau đó, _uiState.messages là source of truth duy nhất (in-memory)
            // → tránh race condition giữa optimistic update và Room Flow emit
            _uiState.update { it.copy(isLoading = true) }

            chatRepository.getAllMessagesByUser(userId)
                .take(1)
                .collect { stored ->
                    val chatMessages = stored.map { model ->
                        ChatMessage(
                            id        = model.id,
                            content   = model.content,
                            sender    = if (model.sender == "user") ChatSender.USER else ChatSender.AI,
                            timestamp = model.timestamp
                        )
                    }
                    messageIdCounter = (chatMessages.maxOfOrNull { it.id } ?: 0L)
                    _uiState.update { state ->
                        state.copy(
                            messages  = chatMessages,
                            isEmpty   = chatMessages.isEmpty(),
                            isLoading = false
                        )
                    }
                }
        }

        // 4. Load tên ví đang active cho chip header
        viewModelScope.launch {
            val userId = settingPreferences.currentUserId.first() ?: return@launch
            // Dùng selectedWalletId nếu được truyền, không thì fallback về ví mặc định
            val wallet = if (selectedWalletId != 0L) {
                runCatching { walletRepository.getWalletById(selectedWalletId) }.getOrNull()
                    ?: runCatching { ensureDefaultWallet(userId) }.getOrNull()
            } else {
                runCatching { ensureDefaultWallet(userId) }.getOrNull()
            }
            Log.d(TAG, "Init: selectedWalletId=$selectedWalletId → loaded wallet id=${wallet?.id} name=${wallet?.name}")
            if (wallet != null) {
                _uiState.update { it.copy(walletName = wallet.name) }
            }
        }
    }

    fun onEvent(event: AddTransactionEvent) {
        when (event) {
            is AddTransactionEvent.OnNoteChanged          -> _uiState.update { it.copy(noteInput = event.note) }
            is AddTransactionEvent.OnSubmitClicked        -> handleSubmit()
            is AddTransactionEvent.OnCameraClicked        -> handleCameraClicked()
            is AddTransactionEvent.OnMicClicked           -> { /* replaced by OnMicPressStart/End */ }
            is AddTransactionEvent.OnMicPressStart        -> handleMicPressStart()
            is AddTransactionEvent.OnMicPressEnd          -> handleMicPressEnd()
            is AddTransactionEvent.OnVoicePlayback        -> handleVoicePlayback()
            is AddTransactionEvent.OnVoiceCancel          -> handleVoiceCancel()
            is AddTransactionEvent.OnParseSettingsClicked -> handleParseSettings()
            is AddTransactionEvent.OnOcrResult            -> _uiState.update { it.copy(noteInput = event.text) }
            is AddTransactionEvent.OnTransferFundClicked  -> { /* TODO */ }
            is AddTransactionEvent.OnRecurringClicked     -> handleRecurring()
        }
    }

    // ──────────────────────────────────────────────────────────────────────────
    // Core flow
    // ──────────────────────────────────────────────────────────────────────────

    private fun handleSubmit() {
        val noteText = _uiState.value.noteInput.trim()
        if (noteText.isBlank() || isWaitingForAI) return

        submitDebounceJob?.cancel()
        submitDebounceJob = viewModelScope.launch {
            kotlinx.coroutines.delay(200L)
            processUserMessage(noteText)
        }
    }

    private suspend fun processUserMessage(noteText: String) {
        isWaitingForAI = true
        val now = System.currentTimeMillis()
        val useGrouping = settingPreferences.isThousandSeparatorEnabled.first()

        // ── Step 1: Hiển thị bubble user + typing indicator ──
        val userMsgId    = ++messageIdCounter
        val typingId     = ++messageIdCounter
        val userBubble   = ChatMessage(id = userMsgId, content = noteText,  sender = ChatSender.USER)
        val typingBubble = ChatMessage(id = typingId,  content = "•••",     sender = ChatSender.AI)

        _uiState.update {
            it.copy(
                messages     = it.messages + userBubble + typingBubble,
                noteInput    = "",
                isEmpty      = false,
                errorMessage = null
            )
        }

        // ── Step 2: Lấy userId ──
        val userId = settingPreferences.currentUserId.first() ?: ""

        // Lưu tin nhắn user vào Room (fire-and-forget)
        viewModelScope.launch {
            runCatching {
                chatRepository.saveMessage(
                    ChatMessageModel(userId = userId, content = noteText,
                        sender = "user", sessionId = sessionId, timestamp = now)
                )
            }
        }

        // ── Step 3: Gọi Groq API ──
        try {
            val result = GroqService.chatWithParsing(noteText)

            // ── Step 4: Xây text AI và cập nhật bubble ──
            val aiText   = buildAIDisplayText(result, useGrouping)
            val aiBubble = ChatMessage(id = typingId, content = aiText, sender = ChatSender.AI)
            _uiState.update { state ->
                state.copy(messages = state.messages.map { if (it.id == typingId) aiBubble else it })
            }

            // Lưu tin nhắn AI vào Room (fire-and-forget)
            viewModelScope.launch {
                runCatching {
                    chatRepository.saveMessage(
                        ChatMessageModel(userId = userId, content = aiText,
                            sender = "ai", sessionId = sessionId,
                            timestamp = System.currentTimeMillis())
                    )
                }
            }

            // ── Step 5 & 6: Xử lý từng giao dịch parse được ──
            if (result.transactions.isNotEmpty() && userId.isNotBlank()) {
                viewModelScope.launch {
                    // Resolve đúng ví đang active (không fallback ngầm về ví mặc định)
                    val wallet = if (selectedWalletId != 0L) {
                        runCatching { walletRepository.getWalletById(selectedWalletId) }.getOrElse { null }
                            ?: run {
                                Log.w(TAG, "selectedWalletId=$selectedWalletId not found, falling back to default")
                                runCatching { ensureDefaultWallet(userId) }.getOrElse { return@launch }
                            }
                    } else {
                        runCatching { ensureDefaultWallet(userId) }.getOrElse {
                            Log.e(TAG, "Cannot get/create wallet: ${it.message}")
                            return@launch
                        }
                    }

                    Log.d(TAG, "▶ Processing batch: selectedWalletId=$selectedWalletId → using wallet id=${wallet.id} name='${wallet.name}'")

                    result.transactions.forEach { parsed ->
                        // ── Lấy số dư hiện tại của ĐÚNG ví (không cộng dồn tất cả ví) ──
                        val currentBalance = runCatching {
                            walletRepository.getWalletById(wallet.id)?.balance ?: 0.0
                        }.getOrElse { 0.0 }

                        Log.d(TAG, "  TX payload: note='${parsed.note}' amount=${parsed.amount} type=${parsed.type} walletId=${wallet.id} currentBalance=$currentBalance")

                        if (parsed.type == "expense" && currentBalance < parsed.amount) {
                            // Số dư không đủ → KHÔNG lưu, thêm bubble cảnh báo
                            val shortfall   = parsed.amount - currentBalance
                            val warnText    = buildInsufficientBalanceText(
                                txNote      = parsed.note,
                                txAmount    = parsed.amount,
                                balance     = currentBalance,
                                shortfall   = shortfall,
                                useGrouping = useGrouping
                            )
                            val warnId  = ++messageIdCounter
                            val warnMsg = ChatMessage(id = warnId, content = warnText, sender = ChatSender.AI)
                            _uiState.update { s -> s.copy(messages = s.messages + warnMsg) }

                            // Lưu cảnh báo vào Room chat history
                            runCatching {
                                chatRepository.saveMessage(
                                    ChatMessageModel(
                                        userId    = userId,
                                        content   = warnText,
                                        sender    = "ai",
                                        sessionId = sessionId,
                                        timestamp = System.currentTimeMillis()
                                    )
                                )
                            }
                            Log.d(TAG, "Insufficient balance: $currentBalance < ${parsed.amount}, skipped")
                            return@forEach  // bỏ qua giao dịch này
                        }

                        // Resolve category name → id (fallback to "Khác" nếu không tìm thấy)
                        val resolvedCategoryId = runCatching {
                            categoryDao.getCategoryByName(userId, parsed.category, parsed.type)?.id
                                ?: categoryDao.getDefaultCategory(userId, parsed.type)?.id
                        }.getOrNull()

                        val transaction = TransactionModel(
                            userId    = userId,
                            note      = parsed.note,
                            amount    = parsed.amount,
                            type      = parsed.type,
                            category  = parsed.category,
                            categoryId = resolvedCategoryId,
                            walletId  = wallet.id,
                            aiGenerated = true,
                            timestamp = now
                        )

                        // 6a. Lưu giao dịch vào Room
                        val saveResult = runCatching { addTransactionUseCase(transaction) }
                        if (saveResult.isFailure) {
                            Log.e(TAG, "Room insert failed: ${saveResult.exceptionOrNull()?.message}")
                            return@forEach
                        }
                        Log.d(TAG, "Saved to Room: ${parsed.note} ${parsed.amount}")

                        // 6b. Cập nhật balance ví
                        //   income  → balance + amount
                        //   expense → balance - amount (đã kiểm tra đủ tiền ở trên)
                        val delta      = if (parsed.type == "income") parsed.amount else -parsed.amount
                        val newBalance = currentBalance + delta
                        runCatching {
                            walletRepository.updateWalletBalance(wallet.id, newBalance)
                        }.onFailure {
                            Log.e(TAG, "Wallet balance update failed: ${it.message}")
                        }
                        Log.d(TAG, "Wallet balance: $currentBalance → $newBalance (delta=$delta)")

                        // 6c. Upload lên Supabase (non-blocking, non-fatal)
                        launch {
                            runCatching {
                                supabaseTransactionRepo.insertTransaction(
                                    userId          = userId,
                                    note            = parsed.note,
                                    amount          = parsed.amount,
                                    type            = parsed.type,
                                    category        = parsed.category,
                                    timestampMillis = now,
                                    walletSupabaseId = wallet.supabaseId  // null nếu ví chưa sync
                                )
                            }.onFailure { Log.w(TAG, "Supabase insert failed (non-critical): ${it.message}") }
                        }
                    }
                }
            }

        } catch (e: Exception) {
            Log.e(TAG, "AI error: ${e.message}", e)
            val errText = mapAIError(e)
            _uiState.update { state ->
                state.copy(
                    messages = state.messages.map {
                        if (it.id == typingId) it.copy(content = errText) else it
                    }
                )
            }
            viewModelScope.launch {
                runCatching {
                    chatRepository.saveMessage(
                        ChatMessageModel(userId = userId, content = errText,
                            sender = "ai", sessionId = sessionId,
                            timestamp = System.currentTimeMillis())
                    )
                }
            }
        } finally {
            isWaitingForAI = false
        }
    }

    // ──────────────────────────────────────────────────────────────────────────
    // Helpers
    // ──────────────────────────────────────────────────────────────────────────

    /**
     * Tạo thông báo AI khi số dư ví không đủ để chi tiêu.
     * Không lưu giao dịch, chỉ hiện cảnh báo.
     */
    private fun buildInsufficientBalanceText(
        txNote: String,
        txAmount: Double,
        balance: Double,
        shortfall: Double,
        useGrouping: Boolean
    ): String {
        val amountFmt   = MoneyFormatter.format(txAmount, useGrouping)
        val balanceFmt  = MoneyFormatter.format(balance, useGrouping)
        val shortFmt    = MoneyFormatter.format(shortfall, useGrouping)
        return "⚠️ Số dư ví không đủ để ghi \"$txNote\"!\n\n" +
                "• Chi tiêu cần: ${amountFmt}đ\n" +
                "• Số dư hiện tại: ${balanceFmt}đ\n" +
                "• Còn thiếu: ${shortFmt}đ\n\n" +
                " Hãy nộp thêm tiền vào ví trước nhé! " +
                "Bạn có thể nhắn \"nạp [số tiền]\" để thêm thu nhập."
    }

    private fun buildAIDisplayText(result: GroqService.ChatResult, useGrouping: Boolean): String {
        if (result.transactions.isEmpty()) return result.displayText

        val txLines = result.transactions.joinToString("\n") { tx ->
            val sign   = if (tx.type == "income") "+" else "-"
            val amount = MoneyFormatter.format(tx.amount, useGrouping)
            "• ${tx.note}: $sign${amount}đ  [${tx.category}]"
        }
        return "${result.displayText}\n\n✅ Đã lưu:\n$txLines"
    }

//    private fun formatAmount(amount: Double): String =
//        String.format(Locale.US, "%,.0f", amount).replace(',', '.')

    private fun handleParseSettings() {
        viewModelScope.launch { _navEvent.emit(AddTransactionNavEvent.NavigateToParseSettings) }
    }

    private fun handleRecurring() {
        viewModelScope.launch { _navEvent.emit(AddTransactionNavEvent.NavigateToRecurring(selectedWalletId)) }
    }

    // ──────────────────────────────────────────────────────────────────────────
    // Voice recording handlers
    // ──────────────────────────────────────────────────────────────────────────

    /** Người dùng bắt đầu nhấn giữ mic → bắt đầu ghi âm */
    private fun handleMicPressStart() {
        if (_uiState.value.voiceState != VoiceRecordingState.IDLE) return
        try {
            voiceRecorder.startRecording()
            _uiState.update { it.copy(voiceState = VoiceRecordingState.RECORDING) }
            Log.d(TAG, "Voice recording started")
        } catch (e: Exception) {
            Log.e(TAG, "Failed to start recording: ${e.message}")
            _uiState.update { it.copy(voiceState = VoiceRecordingState.IDLE) }
        }
    }

    /** Người dùng thả mic → dừng ghi, gửi Groq Whisper để nhận dạng */
    private fun handleMicPressEnd() {
        if (_uiState.value.voiceState != VoiceRecordingState.RECORDING) {
            voiceRecorder.stopRecording()
            return
        }
        val audioFile = voiceRecorder.stopRecording()
        if (audioFile == null || !audioFile.exists() || audioFile.length() < 1000L) {
            voiceRecorder.deleteRecording()
            _uiState.update { it.copy(voiceState = VoiceRecordingState.IDLE) }
            Log.d(TAG, "Recording too short or failed, discarded")
            return
        }
        _uiState.update { it.copy(voiceState = VoiceRecordingState.PROCESSING) }
        viewModelScope.launch {
            try {
                val transcript = GroqService.transcribeAudio(audioFile)
                if (transcript.isNotBlank()) {
                    _uiState.update { state ->
                        state.copy(noteInput = transcript, voiceState = VoiceRecordingState.RECORDED)
                    }
                    Log.d(TAG, "Transcript: $transcript")
                } else {
                    voiceRecorder.deleteRecording()
                    _uiState.update { it.copy(voiceState = VoiceRecordingState.IDLE) }
                }
            } catch (e: Exception) {
                Log.e(TAG, "Transcription failed: ${e.message}")
                voiceRecorder.deleteRecording()
                _uiState.update { it.copy(voiceState = VoiceRecordingState.IDLE) }
            }
        }
    }

    /** Phát lại / dừng phát âm thanh đã ghi */
    private fun handleVoicePlayback() {
        if (voiceRecorder.isPlaying()) {
            voiceRecorder.stopPlayback()
            _uiState.update { it.copy(isVoicePlaying = false) }
        } else {
            _uiState.update { it.copy(isVoicePlaying = true) }
            voiceRecorder.startPlayback {
                _uiState.update { it.copy(isVoicePlaying = false) }
            }
        }
    }

    /** Hủy bỏ ghi âm và xóa văn bản đã nhận dạng */
    private fun handleVoiceCancel() {
        voiceRecorder.deleteRecording()
        _uiState.update { state ->
            state.copy(voiceState = VoiceRecordingState.IDLE, isVoicePlaying = false, noteInput = "")
        }
    }

    override fun onCleared() {
        super.onCleared()
        voiceRecorder.release()
    }

    private fun mapAIError(e: Exception): String {
        val msg = e.message?.lowercase() ?: return "⚠️ Có lỗi xảy ra. Vui lòng thử lại."
        return when {
            "not configured" in msg || "groq_api_key" in msg ->
                "⚠️ API key chưa cấu hình. Thêm GROQ_API_KEY vào local.properties."
            "api key" in msg || "authentication" in msg || "api_key_invalid" in msg ->
                "⚠️ API key không hợp lệ. Kiểm tra tại https://console.groq.com/keys"
            "network" in msg || "connect" in msg || "timeout" in msg ->
                "⚠️ Lỗi kết nối mạng. Kiểm tra internet và thử lại."
            "rate limit" in msg || "quota exceeded" in msg ->
                "⚠️ Quá nhiều yêu cầu. Vui lòng đợi rồi thử lại."
            else -> "⚠️ ${e.message ?: "Lỗi không xác định"}. Vui lòng thử lại."
        }
    }

    companion object {
        fun factory(context: android.content.Context, walletId: Long = 0L) =
            AddTransactionViewModelFactory(context, walletId)
    }
}

package com.example.mymoney.presentation.viewmodel.addtransaction

import android.util.Log
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.mymoney.data.audio.VoiceRecorder
import com.example.mymoney.data.local.dao.CategoryDao
import com.example.mymoney.data.local.datastore.SettingPreferences
import com.example.mymoney.data.remote.GroqService
import com.example.mymoney.data.repository.SupabaseTransactionRepository
import com.example.mymoney.domain.model.ChatMessageModel
import com.example.mymoney.domain.model.TransactionModel
import com.example.mymoney.domain.repository.ChatRepository
import com.example.mymoney.domain.repository.WalletRepository
import com.example.mymoney.domain.usecase.AddTransactionUseCase
import com.example.mymoney.domain.usecase.EnsureDefaultWalletUseCase
import com.example.mymoney.domain.usecase.GetTransactionsUseCase
import com.example.mymoney.domain.usecase.MoneyFormatter
import com.example.mymoney.presentation.viewmodel.addtransaction.addtransaction.AddTransactionEvent
import com.example.mymoney.presentation.viewmodel.addtransaction.addtransaction.AddTransactionNavEvent
import com.example.mymoney.presentation.viewmodel.addtransaction.addtransaction.AddTransactionUiState
import com.example.mymoney.presentation.viewmodel.addtransaction.addtransaction.ChatMessage
import com.example.mymoney.presentation.viewmodel.addtransaction.addtransaction.ChatSender
import com.example.mymoney.presentation.viewmodel.addtransaction.addtransaction.VoiceRecordingState
import kotlinx.coroutines.Job
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.take
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

/**
 * ViewModel cho AIChatScreen.
 *
 * Luồng đầy đủ khi user nhắn "bữa tối 20k":
 *  1. Hiển thị bubble user + bubble "..." ngay lập tức
 *  2. Lưu tin nhắn user vào Room (chat_messages)
 *  3. Gọi Groq API → parse ra { note, amount, type, category }
 *  4. Thay "..." bằng phản hồi AI
 *  5. Lưu tin nhắn AI vào Room
 *  6. Với mỗi giao dịch parse được:
 *     a. Lấy/tạo ví mặc định của user
 *     b. Lưu TransactionModel vào Room (kèm walletId)
 *     c. Cập nhật balance ví trong Room (income → cộng, expense → trừ)
 *     d. Lưu lên Supabase song song (không block UI)
 */
class AddTransactionViewModel(
    @Suppress("unused")
    private val getTransactionsUseCase: GetTransactionsUseCase,
    private val addTransactionUseCase: AddTransactionUseCase,
    private val walletRepository: WalletRepository,
    private val ensureDefaultWallet: EnsureDefaultWalletUseCase,
    private val chatRepository: ChatRepository,
    private val supabaseTransactionRepo: SupabaseTransactionRepository,
    private val settingPreferences: SettingPreferences,
    private val categoryDao: CategoryDao,
    /** ID ví đang active trên HomeScreen. 0L = chưa chọn → fallback về ví mặc định. */
    private val selectedWalletId: Long = 0L,
    /** ApplicationContext để tạo VoiceRecorder */
    appContext: android.content.Context
) : ViewModel() {

    private val TAG = "AddTransactionVM"

    private val voiceRecorder = VoiceRecorder(appContext)

    private val _uiState = MutableStateFlow(AddTransactionUiState())
    val uiState: StateFlow<AddTransactionUiState> = _uiState.asStateFlow()

    private val _navEvent = MutableSharedFlow<AddTransactionNavEvent>()
    val navEvent: SharedFlow<AddTransactionNavEvent> = _navEvent.asSharedFlow()

    // sessionId là field của ViewModel — KHÔNG nằm trong UiState
    // → tạo 1 lần duy nhất, không mất khi recompose
    // → restore = dùng lại sessionId cũ nhất của user
    private var sessionId: String = java.util.UUID.randomUUID().toString()

    private var messageIdCounter = 0L
    private var isWaitingForAI = false
    private var submitDebounceJob: Job? = null

    init {
        viewModelScope.launch {
            // 1. Xóa tin nhắn cũ > 48h
            runCatching { chatRepository.deleteOldMessages() }

            val userId = settingPreferences.currentUserId.first() ?: return@launch

            // 2. Seed danh mục mặc định nếu chưa có (idempotent)
            runCatching {
                com.example.mymoney.data.repository.CategoryRepositoryImpl(categoryDao)
                    .seedDefaultCategories(userId)
            }

            // 2. Restore sessionId của phiên gần nhất (nếu có)
            val latestSession = runCatching {
                chatRepository.getLatestSessionId(userId)
            }.getOrNull()

            if (latestSession != null) {
                // Có lịch sử → dùng lại session cũ
                sessionId = latestSession
            }
            // Nếu null → giữ sessionId mới tạo (lần đầu dùng app)

            // 3. Load lịch sử tin nhắn từ Room một lần (take(1)) khi khởi động
            // Sau đó, _uiState.messages là source of truth duy nhất (in-memory)
            // → tránh race condition giữa optimistic update và Room Flow emit
            _uiState.update { it.copy(isLoading = true) }

            chatRepository.getAllMessagesByUser(userId)
                .take(1)
                .collect { stored ->
                    val chatMessages = stored.map { model ->
                        ChatMessage(
                            id        = model.id,
                            content   = model.content,
                            sender    = if (model.sender == "user") ChatSender.USER else ChatSender.AI,
                            timestamp = model.timestamp
                        )
                    }
                    messageIdCounter = (chatMessages.maxOfOrNull { it.id } ?: 0L)
                    _uiState.update { state ->
                        state.copy(
                            messages  = chatMessages,
                            isEmpty   = chatMessages.isEmpty(),
                            isLoading = false
                        )
                    }
                }
        }

        // 4. Load tên ví đang active cho chip header
        viewModelScope.launch {
            val userId = settingPreferences.currentUserId.first() ?: return@launch
            // Dùng selectedWalletId nếu được truyền, không thì fallback về ví mặc định
            val wallet = if (selectedWalletId != 0L) {
                runCatching { walletRepository.getWalletById(selectedWalletId) }.getOrNull()
                    ?: runCatching { ensureDefaultWallet(userId) }.getOrNull()
            } else {
                runCatching { ensureDefaultWallet(userId) }.getOrNull()
            }
            Log.d(TAG, "Init: selectedWalletId=$selectedWalletId → loaded wallet id=${wallet?.id} name=${wallet?.name}")
            if (wallet != null) {
                _uiState.update { it.copy(walletName = wallet.name) }
            }
        }
    }

    fun onEvent(event: AddTransactionEvent) {
        when (event) {
            is AddTransactionEvent.OnNoteChanged          -> _uiState.update { it.copy(noteInput = event.note) }
            is AddTransactionEvent.OnSubmitClicked        -> handleSubmit()
            is AddTransactionEvent.OnCameraClicked        -> handleCameraClicked()
            is AddTransactionEvent.OnMicClicked           -> { /* replaced by OnMicPressStart/End */ }
            is AddTransactionEvent.OnMicPressStart        -> handleMicPressStart()
            is AddTransactionEvent.OnMicPressEnd          -> handleMicPressEnd()
            is AddTransactionEvent.OnVoicePlayback        -> handleVoicePlayback()
            is AddTransactionEvent.OnVoiceCancel          -> handleVoiceCancel()
            is AddTransactionEvent.OnParseSettingsClicked -> handleParseSettings()
            is AddTransactionEvent.OnOcrResult            -> _uiState.update { it.copy(noteInput = event.text) }
            is AddTransactionEvent.OnTransferFundClicked  -> { /* TODO */ }
            is AddTransactionEvent.OnRecurringClicked     -> handleRecurring()
        }
    }

    // ──────────────────────────────────────────────────────────────────────────
    // Core flow
    // ──────────────────────────────────────────────────────────────────────────

    private fun handleSubmit() {
        val noteText = _uiState.value.noteInput.trim()
        if (noteText.isBlank() || isWaitingForAI) return

        submitDebounceJob?.cancel()
        submitDebounceJob = viewModelScope.launch {
            kotlinx.coroutines.delay(200L)
            processUserMessage(noteText)
        }
    }

    /** Người dùng nhấn nút camera → yêu cầu UI mở màn hình chụp ảnh */
    private fun handleCameraClicked() {
        viewModelScope.launch {
            _navEvent.emit(AddTransactionNavEvent.NavigateToCameraCapture(selectedWalletId))
        }
    }

    private suspend fun processUserMessage(noteText: String) {
        isWaitingForAI = true
        val now = System.currentTimeMillis()
        val useGrouping = settingPreferences.isThousandSeparatorEnabled.first()

        // ── Step 1: Hiển thị bubble user + typing indicator ──
        val userMsgId    = ++messageIdCounter
        val typingId     = ++messageIdCounter
        val userBubble   = ChatMessage(id = userMsgId, content = noteText,  sender = ChatSender.USER)
        val typingBubble = ChatMessage(id = typingId,  content = "•••",     sender = ChatSender.AI)

        _uiState.update {
            it.copy(
                messages     = it.messages + userBubble + typingBubble,
                noteInput    = "",
                isEmpty      = false,
                errorMessage = null
            )
        }

        // ── Step 2: Lấy userId ──
        val userId = settingPreferences.currentUserId.first() ?: ""

        // Lưu tin nhắn user vào Room (fire-and-forget)
        viewModelScope.launch {
            runCatching {
                chatRepository.saveMessage(
                    ChatMessageModel(userId = userId, content = noteText,
                        sender = "user", sessionId = sessionId, timestamp = now)
                )
            }
        }

        // ── Step 3: Gọi Groq API ──
        try {
            val result = GroqService.chatWithParsing(noteText)

            // ── Step 4: Xây text AI và cập nhật bubble ──
            val aiText   = buildAIDisplayText(result, useGrouping)
            val aiBubble = ChatMessage(id = typingId, content = aiText, sender = ChatSender.AI)
            _uiState.update { state ->
                state.copy(messages = state.messages.map { if (it.id == typingId) aiBubble else it })
            }

            // Lưu tin nhắn AI vào Room (fire-and-forget)
            viewModelScope.launch {
                runCatching {
                    chatRepository.saveMessage(
                        ChatMessageModel(userId = userId, content = aiText,
                            sender = "ai", sessionId = sessionId,
                            timestamp = System.currentTimeMillis())
                    )
                }
            }

            // ── Step 5 & 6: Xử lý từng giao dịch parse được ──
            if (result.transactions.isNotEmpty() && userId.isNotBlank()) {
                viewModelScope.launch {
                    // Resolve đúng ví đang active (không fallback ngầm về ví mặc định)
                    val wallet = if (selectedWalletId != 0L) {
                        runCatching { walletRepository.getWalletById(selectedWalletId) }.getOrElse { null }
                            ?: run {
                                Log.w(TAG, "selectedWalletId=$selectedWalletId not found, falling back to default")
                                runCatching { ensureDefaultWallet(userId) }.getOrElse { return@launch }
                            }
                    } else {
                        runCatching { ensureDefaultWallet(userId) }.getOrElse {
                            Log.e(TAG, "Cannot get/create wallet: ${it.message}")
                            return@launch
                        }
                    }

                    Log.d(TAG, "▶ Processing batch: selectedWalletId=$selectedWalletId → using wallet id=${wallet.id} name='${wallet.name}'")

                    result.transactions.forEach { parsed ->
                        // ── Lấy số dư hiện tại của ĐÚNG ví (không cộng dồn tất cả ví) ──
                        val currentBalance = runCatching {
                            walletRepository.getWalletById(wallet.id)?.balance ?: 0.0
                        }.getOrElse { 0.0 }

                        Log.d(TAG, "  TX payload: note='${parsed.note}' amount=${parsed.amount} type=${parsed.type} walletId=${wallet.id} currentBalance=$currentBalance")

                        if (parsed.type == "expense" && currentBalance < parsed.amount) {
                            // Số dư không đủ → KHÔNG lưu, thêm bubble cảnh báo
                            val shortfall   = parsed.amount - currentBalance
                            val warnText    = buildInsufficientBalanceText(
                                txNote      = parsed.note,
                                txAmount    = parsed.amount,
                                balance     = currentBalance,
                                shortfall   = shortfall,
                                useGrouping = useGrouping
                            )
                            val warnId  = ++messageIdCounter
                            val warnMsg = ChatMessage(id = warnId, content = warnText, sender = ChatSender.AI)
                            _uiState.update { s -> s.copy(messages = s.messages + warnMsg) }

                            // Lưu cảnh báo vào Room chat history
                            runCatching {
                                chatRepository.saveMessage(
                                    ChatMessageModel(
                                        userId    = userId,
                                        content   = warnText,
                                        sender    = "ai",
                                        sessionId = sessionId,
                                        timestamp = System.currentTimeMillis()
                                    )
                                )
                            }
                            Log.d(TAG, "Insufficient balance: $currentBalance < ${parsed.amount}, skipped")
                            return@forEach  // bỏ qua giao dịch này
                        }

                        // Resolve category name → id (fallback to "Khác" nếu không tìm thấy)
                        val resolvedCategoryId = runCatching {
                            categoryDao.getCategoryByName(userId, parsed.category, parsed.type)?.id
                                ?: categoryDao.getDefaultCategory(userId, parsed.type)?.id
                        }.getOrNull()

                        val transaction = TransactionModel(
                            userId    = userId,
                            note      = parsed.note,
                            amount    = parsed.amount,
                            type      = parsed.type,
                            category  = parsed.category,
                            categoryId = resolvedCategoryId,
                            walletId  = wallet.id,
                            aiGenerated = true,
                            timestamp = now
                        )

                        // 6a. Lưu giao dịch vào Room
                        val saveResult = runCatching { addTransactionUseCase(transaction) }
                        if (saveResult.isFailure) {
                            Log.e(TAG, "Room insert failed: ${saveResult.exceptionOrNull()?.message}")
                            return@forEach
                        }
                        Log.d(TAG, "Saved to Room: ${parsed.note} ${parsed.amount}")

                        // 6b. Cập nhật balance ví
                        //   income  → balance + amount
                        //   expense → balance - amount (đã kiểm tra đủ tiền ở trên)
                        val delta      = if (parsed.type == "income") parsed.amount else -parsed.amount
                        val newBalance = currentBalance + delta
                        runCatching {
                            walletRepository.updateWalletBalance(wallet.id, newBalance)
                        }.onFailure {
                            Log.e(TAG, "Wallet balance update failed: ${it.message}")
                        }
                        Log.d(TAG, "Wallet balance: $currentBalance → $newBalance (delta=$delta)")

                        // 6c. Upload lên Supabase (non-blocking, non-fatal)
                        launch {
                            runCatching {
                                supabaseTransactionRepo.insertTransaction(
                                    userId          = userId,
                                    note            = parsed.note,
                                    amount          = parsed.amount,
                                    type            = parsed.type,
                                    category        = parsed.category,
                                    timestampMillis = now,
                                    walletSupabaseId = wallet.supabaseId  // null nếu ví chưa sync
                                )
                            }.onFailure { Log.w(TAG, "Supabase insert failed (non-critical): ${it.message}") }
                        }
                    }
                }
            }

        } catch (e: Exception) {
            Log.e(TAG, "AI error: ${e.message}", e)
            val errText = mapAIError(e)
            _uiState.update { state ->
                state.copy(
                    messages = state.messages.map {
                        if (it.id == typingId) it.copy(content = errText) else it
                    }
                )
            }
            viewModelScope.launch {
                runCatching {
                    chatRepository.saveMessage(
                        ChatMessageModel(userId = userId, content = errText,
                            sender = "ai", sessionId = sessionId,
                            timestamp = System.currentTimeMillis())
                    )
                }
            }
        } finally {
            isWaitingForAI = false
        }
    }

    // ──────────────────────────────────────────────────────────────────────────
    // Helpers
    // ──────────────────────────────────────────────────────────────────────────

    /**
     * Tạo thông báo AI khi số dư ví không đủ để chi tiêu.
     * Không lưu giao dịch, chỉ hiện cảnh báo.
     */
    private fun buildInsufficientBalanceText(
        txNote: String,
        txAmount: Double,
        balance: Double,
        shortfall: Double,
        useGrouping: Boolean
    ): String {
        val amountFmt   = MoneyFormatter.format(txAmount, useGrouping)
        val balanceFmt  = MoneyFormatter.format(balance, useGrouping)
        val shortFmt    = MoneyFormatter.format(shortfall, useGrouping)
        return "⚠️ Số dư ví không đủ để ghi \"$txNote\"!\n\n" +
                "• Chi tiêu cần: ${amountFmt}đ\n" +
                "• Số dư hiện tại: ${balanceFmt}đ\n" +
                "• Còn thiếu: ${shortFmt}đ\n\n" +
                " Hãy nộp thêm tiền vào ví trước nhé! " +
                "Bạn có thể nhắn \"nạp [số tiền]\" để thêm thu nhập."
    }

    private fun buildAIDisplayText(result: GroqService.ChatResult, useGrouping: Boolean): String {
        if (result.transactions.isEmpty()) return result.displayText

        val txLines = result.transactions.joinToString("\n") { tx ->
            val sign   = if (tx.type == "income") "+" else "-"
            val amount = MoneyFormatter.format(tx.amount, useGrouping)
            "• ${tx.note}: $sign${amount}đ  [${tx.category}]"
        }
        return "${result.displayText}\n\n✅ Đã lưu:\n$txLines"
    }

//    private fun formatAmount(amount: Double): String =
//        String.format(Locale.US, "%,.0f", amount).replace(',', '.')

    private fun handleParseSettings() {
        viewModelScope.launch { _navEvent.emit(AddTransactionNavEvent.NavigateToParseSettings) }
    }

    private fun handleRecurring() {
        viewModelScope.launch { _navEvent.emit(AddTransactionNavEvent.NavigateToRecurring(selectedWalletId)) }
    }

    // ──────────────────────────────────────────────────────────────────────────
    // Voice recording handlers
    // ──────────────────────────────────────────────────────────────────────────

    /** Người dùng bắt đầu nhấn giữ mic → bắt đầu ghi âm */
    private fun handleMicPressStart() {
        if (_uiState.value.voiceState != VoiceRecordingState.IDLE) return
        try {
            voiceRecorder.startRecording()
            _uiState.update { it.copy(voiceState = VoiceRecordingState.RECORDING) }
            Log.d(TAG, "Voice recording started")
        } catch (e: Exception) {
            Log.e(TAG, "Failed to start recording: ${e.message}")
            _uiState.update { it.copy(voiceState = VoiceRecordingState.IDLE) }
        }
    }

    /** Người dùng thả mic → dừng ghi, gửi Groq Whisper để nhận dạng */
    private fun handleMicPressEnd() {
        if (_uiState.value.voiceState != VoiceRecordingState.RECORDING) {
            voiceRecorder.stopRecording()
            return
        }
        val audioFile = voiceRecorder.stopRecording()
        if (audioFile == null || !audioFile.exists() || audioFile.length() < 1000L) {
            voiceRecorder.deleteRecording()
            _uiState.update { it.copy(voiceState = VoiceRecordingState.IDLE) }
            Log.d(TAG, "Recording too short or failed, discarded")
            return
        }
        _uiState.update { it.copy(voiceState = VoiceRecordingState.PROCESSING) }
        viewModelScope.launch {
            try {
                val transcript = GroqService.transcribeAudio(audioFile)
                if (transcript.isNotBlank()) {
                    _uiState.update { state ->
                        state.copy(noteInput = transcript, voiceState = VoiceRecordingState.RECORDED)
                    }
                    Log.d(TAG, "Transcript: $transcript")
                } else {
                    voiceRecorder.deleteRecording()
                    _uiState.update { it.copy(voiceState = VoiceRecordingState.IDLE) }
                }
            } catch (e: Exception) {
                Log.e(TAG, "Transcription failed: ${e.message}")
                voiceRecorder.deleteRecording()
                _uiState.update { it.copy(voiceState = VoiceRecordingState.IDLE) }
            }
        }
    }

    /** Phát lại / dừng phát âm thanh đã ghi */
    private fun handleVoicePlayback() {
        if (voiceRecorder.isPlaying()) {
            voiceRecorder.stopPlayback()
            _uiState.update { it.copy(isVoicePlaying = false) }
        } else {
            _uiState.update { it.copy(isVoicePlaying = true) }
            voiceRecorder.startPlayback {
                _uiState.update { it.copy(isVoicePlaying = false) }
            }
        }
    }

    /** Hủy bỏ ghi âm và xóa văn bản đã nhận dạng */
    private fun handleVoiceCancel() {
        voiceRecorder.deleteRecording()
        _uiState.update { state ->
            state.copy(voiceState = VoiceRecordingState.IDLE, isVoicePlaying = false, noteInput = "")
        }
    }

    override fun onCleared() {
        super.onCleared()
        voiceRecorder.release()
    }

    private fun mapAIError(e: Exception): String {
        val msg = e.message?.lowercase() ?: return "⚠️ Có lỗi xảy ra. Vui lòng thử lại."
        return when {
            "not configured" in msg || "groq_api_key" in msg ->
                "⚠️ API key chưa cấu hình. Thêm GROQ_API_KEY vào local.properties."
            "api key" in msg || "authentication" in msg || "api_key_invalid" in msg ->
                "⚠️ API key không hợp lệ. Kiểm tra tại https://console.groq.com/keys"
            "network" in msg || "connect" in msg || "timeout" in msg ->
                "⚠️ Lỗi kết nối mạng. Kiểm tra internet và thử lại."
            "rate limit" in msg || "quota exceeded" in msg ->
                "⚠️ Quá nhiều yêu cầu. Vui lòng đợi rồi thử lại."
            else -> "⚠️ ${e.message ?: "Lỗi không xác định"}. Vui lòng thử lại."
        }
    }

    companion object {
        fun factory(context: android.content.Context, walletId: Long = 0L) =
            AddTransactionViewModelFactory(context, walletId)
    }
}

package com.example.mymoney.presentation.viewmodel.setting

import android.content.Context
import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import com.example.mymoney.data.local.datastore.SettingPreferences
import com.example.mymoney.data.local.db.AppDatabase
import com.example.mymoney.data.repository.AuthRepositoryImpl
import com.example.mymoney.data.repository.SupabaseTransactionRepository
import com.example.mymoney.data.repository.TransactionRepositoryImpl

/**
 * Factory inject toàn bộ dependency chain:
 *   AppDatabase → DAO → RepositoryImpl → SettingViewModel
 *
 * @param context  ApplicationContext (hoặc Activity context)
 * @param userId   ID người dùng hiện tại — dùng để filter Room queries theo user
 */
class SettingViewModelFactory(
    private val context: Context
) : ViewModelProvider.Factory {

    @Suppress("UNCHECKED_CAST")
    override fun <T : ViewModel> create(modelClass: Class<T>): T {
        require(modelClass.isAssignableFrom(SettingViewModel::class.java)) {
            "Unknown ViewModel: ${modelClass.name}"
        }
        val appCtx = context.applicationContext
        val db     = AppDatabase.getInstance(appCtx)

        return SettingViewModel(
            settingPreferences      = SettingPreferences(appCtx),
            authRepository          = AuthRepositoryImpl(),
            transactionRepository   = TransactionRepositoryImpl(db.transactionDao()),
            supabaseTransactionRepo = SupabaseTransactionRepository(db.categoryDao())
        ) as T
    }
}

